#!/usr/bin/env bash
# Hyprland 0.57+ gets a hyprland.lua that loads your hyprland.conf
#
# Hyprland 0.57 stopped reading hyprland.conf: it reads ~/.config/hypr/hyprland.lua,
# and when there is none it writes a default one — so the desktop came up as plain
# Hyprland with none of Prime (no bar, no dock, no shortcuts). Prime's
# hyprland.lua reads hyprland.conf through layer/default/hypr/prime.lua, so
# every .conf file keeps working. Older Hyprland ignores hyprland.lua.
#   none yet                 → Prime's is put there
#   Hyprland's autogenerated → moved aside to hyprland.lua.autogenerated, Prime's put there
#   already Prime's          → left alone
#   one you wrote            → left alone (add the two lines from Prime's to it)
LAYER="${PRIME_LAYER:?}"
DST="$HOME/.config/hypr/hyprland.lua"
SEED="$LAYER/seed/hypr/hyprland.lua"
mkdir -p "$(dirname "$DST")"
if [ -f "$DST" ]; then
    grep -q 'prime-linux' "$DST" && exit 0
    if grep -q 'autogenerated = true' "$DST" || cmp -s "$DST" /usr/share/hypr/hyprland.lua; then
        mv "$DST" "$DST.autogenerated"
    else
        echo "    ~/.config/hypr/hyprland.lua is your own: on Hyprland 0.57+ add Prime's two lines from $SEED" >&2
        exit 0
    fi
fi
install -m644 "$SEED" "$DST"
exit 0
